    final probeId = 'fa-dap-probe-${_nonce()}';
    late final StreamSubscription sub;
    sub = ws.listen((dynamic data) => _onProbeFrame(answer, probeId, data));
    ws.add(jsonEncode({'op': 'presence_query', 'id': probeId}));
