    try {
      final http = HttpClient()..connectionTimeout = const Duration(seconds: 1);
      final response = await (await http.get(
        _uri.host,
        _uri.port,
        '/healthz',
      )).close();
      await response.drain<void>();
      http.close();
      return response.statusCode == 200;
    } on Object {
      return false;
    }
  }

