    final outcome = await _promptedMasterDial(prompt);
    if (outcome == null) break;
    if (outcome.ok) return _finishCredential();
    if (outcome.unauthorized && attempt < 3) {
      say('enrollment rejected (wrong master key) — try again');
    } else {
      break;
    }
