        prompt: (q) {
          prompts.add(q);
          return Future.value('k1-master-key');
        },
      );
      final code2 = await controller2.start();
      final out2 = sinkOf(controller2).join('\n');
      expect(code2, 0, reason: out2);
      expect(out2, contains('already running'));
      expect(
        prompts,
