/// the master this start resolved, the persisted state's master,
/// then a bare open-hub enroll.
List<(String?, bool)> _credentialAttempts({
  required Object? cachedSecret,
  String? knownMaster,
}) => [
  if (cachedSecret is String && cachedSecret.isNotEmpty)
