      home ?? environment['HOME'] ?? environment['USERPROFILE'] ?? '.';

  File get _stateFile =>
      defaultHubStateFile(home: home, environment: environment);

  String get _configPath => client.defaultDapConfigFile(home, environment);

  File get _pidFile =>
