      return (kind: DapHubProbeKind.down, peers: const <String>[]);
    }
    var sawUnauthorized = false;
    for (final credential in _probeCredentials()) {
      try {
        final peers = await _presenceProbe(credential);
        return (
          kind: DapHubProbeKind.running,
