  if (!_dapEnabled) {
    try {
      _environment[hub.envMasterSecret] = _generateSessionSecret();
    } on Object {
      context.io.writeln(
        '[hub] this host\'s environment is read-only — export '
        'DAP_MASTER_SECRET before launching instead',
      );
      return;
    }
    context.io.writeln(
      'master secret generated for this session — '
